                    $coordinates = json_decode($coordinates, true);
                }

                return [
                    'id' => $geofence->id,
                    'name' => $geofence->name,
                    'geofence_type' => $geofence->geofence_type,
                    'coordinates' => $coordinates, // Already an array thanks to cast
                ];
            })

