ArgumentTypeCoercion.code:
function (Machine $machine) use ($issues) {
                if (! $machine->last_location_update) {
                    $issues->push($this->finding($machine, 'missing_data', 'status is active but last_location_update has never been set'));

                    return;
                }

                $staleness = Carbon::parse($machine->last_location_update)->diffInHours(now());

                if ($staleness > 24) {
                    $issues->push($this->finding(
                        $machine,
                        'stale_telemetry',
                        "status is active but last location update was {$staleness}h ago"
                    ));
                }
            }

function (ProductionRecord $record) use ($issues) {
                if (is_null($record->quantity_produced)) {
                    $issues->push($this->finding($record, 'missing_data', 'quantity_produced is null'));
                } elseif ($record->quantity_produced < 0) {
                    $issues->push($this->finding($record, 'impossible_value', "quantity_produced is negative ({$record->quantity_produced})"));
                }

                if ($record->record_date && $record->record_date->greaterThan(now()->addDay())) {
                    $issues->push($this->finding($record, 'invalid_timestamp', "record_date ({$record->record_date->toDateString()}) is in the future"));
                }
            }

MixedReturnStatement.code:
DB::transaction(function () use ($data) {
            // currency wasn't in $fillable until it was wired up to
            // Team::currency (see Team::$fillable) -- default new
            // transactions to the team's chosen currency rather than the
            // fuel_transactions column's hardcoded 'ZAR' default.
            if (! isset($data['currency']) && isset($data['team_id'])) {
                $data['currency'] = Team::find($data['team_id'])?->currency ?? 'ZAR';
            }

            $transaction = FuelTransaction::create($data);

            // Update tank level based on transaction type
            if ($transaction->fuel_tank_id) {
                $this->updateTankLevel($transaction);
            }

            // Check for alerts after transaction
            $this->checkAndCreateAlerts($transaction);

            // Update budget if applicable
            if ($transaction->total_cost) {
                $this->updateBudget($transaction);
            }

            return $transaction->load(['fuelTank', 'machine', 'user']);
        })

UndefinedMagicMethod.code:
Machine::create([
                    'team_id' => $integration->team_id,
                    // machines.mine_area_id is NOT NULL on MySQL/Postgres
                    // (2026_02_19_000010) and this create() never set it, so
                    // on those drivers every machine insert from a sync died
                    // on the constraint -- silently, because syncMachine()
                    // catches and logs. Default to the team's first active
                    // area, the exact same default that migration's own
                    // backfill used; a dispatcher can reassign from Fleet.
                    'mine_area_id' => MineArea::where('team_id', $integration->team_id)
                        ->where('status', 'active')
                        ->orderBy('id')
                        ->value('id'),
                    'name' => $machineData['model'] ?? 'Unknown Machine',
                    // machine_type is NOT NULL with no default and this
                    // create() never set it at all; manufacturer telemetry
                    // APIs don't return this app's own adt/excavator/dozer/
                    // etc categorization, so 'other' is the honest fallback
                    // -- a real user can reclassify it from the Fleet page.
                    'machine_type' => $machineData['type'] ?? 'other',
                    'manufacturer' => $integration->provider,
                    'model' => $machineData['model'] ?? null,
                    'serial_number' => $machineData['serial_number'] ?? null,
                    'manufacturer_id' => $externalId,
                    'integration_id' => $integration->id,
                    'status' => $machineData['status'] ?? 'idle',
                    'last_location_latitude' => $machineData['last_location']['latitude'] ?? null,
                    'last_location_longitude' => $machineData['last_location']['longitude'] ?? null,
                    'capacity' => $machineData['capacity'] ?? null,
                ])

